pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Pausable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

// --- Interfaces ---

/**
 * @title IINRT
 * @dev Interface for the INRT token contract to allow the hook to call it.
 */
interface IINRT {
    function requestWithdrawal(bytes32 requestId, address user, uint256 amount, string calldata upiId) external;
    function burnForWithdrawal(bytes32 requestId) external;
}

// --- Minimal Uniswap v4 Interfaces ---

// Struct for identifying a pool
struct PoolKey {
    address currency0;
    address currency1;
    uint24 fee;
    int24 tickSpacing;
    address hooks;
}

/**
 * @title IPoolManager
 * @dev Minimal interface for Uniswap v4 PoolManager.
 */
interface IPoolManager {
    struct SwapParams {
        bool zeroForOne;
        int256 amountSpecified;
        uint160 sqrtPriceLimitX96;
    }

    function lock(bytes calldata data) external returns (bytes memory);
    function mint(address, int24, int24, uint128, bytes calldata) external returns (uint256, uint256);
}

/**
 * @title IHooks
 * @dev Minimal interface for Uniswap v4 Hooks.
 */
interface IHooks {
    function afterSwap(address sender, IPoolManager.SwapParams calldata params, bytes calldata data) external returns (bytes4);
}

/**
 * @title BaseHook
 * @dev Base contract for Uniswap v4 Hooks. Provides poolManagerOnly modifier.
 * The address of the pool manager is msg.sender in the `install` call.
 */
abstract contract BaseHook is IHooks {
    IPoolManager internal i_poolManager;

    modifier poolManagerOnly() {
        if (msg.sender != address(i_poolManager)) revert("Not PoolManager");
        _;
    }
}


// --- Main Contracts ---


/**
 * @title INRT
 * @notice An ERC20 token backed 1:1 by Indian Rupees (INR).
 * @dev This contract manages the minting, burning, and withdrawal process for INRT.
 * It is pausable and owned by a single administrator.
 */
contract INRT is ERC20Pausable, Ownable {
    uint256 public totalBankReserves;
    address public authorizedHook;

    mapping(string => bool) private _processedBankTxIds;

    struct Withdrawal {
        address user;
        uint256 amount;
        string upiId;
        uint256 timestamp;
        bool processed;
    }

    mapping(bytes32 => Withdrawal) public withdrawals;

    event TokensMinted(address indexed to, uint256 amount, string bankTxId);
    event TokensBurned(address indexed from, uint256 amount, bytes32 indexed withdrawalRequestId);
    event WithdrawalRequested(bytes32 indexed requestId, address indexed user, uint256 amount, string upiId);
    event WithdrawalProcessed(bytes32 indexed requestId);
    event HookAuthorizationChanged(address indexed hook, bool authorized);

    modifier onlyAuthorizedHook() {
        require(msg.sender == authorizedHook, "INRT: Caller is not the authorized hook");
        _;
    }

    constructor() ERC20("Indian Rupee Token", "INRT") {
        // No arguments as per requirements.
    }

    /**
     * @dev Returns the number of decimals used to get its user representation.
     */
    function decimals() public pure override returns (uint8) {
        return 18;
    }

    /// @dev See {ERC20Pausable-_beforeTokenTransfer}.
    function _beforeTokenTransfer(address from, address to, uint256 amount) internal virtual override(ERC20Pausable) {
        super._beforeTokenTransfer(from, to, amount);
    }

    /**
     * @notice Mints new INRT tokens against a confirmed bank deposit.
     * @param to The address to receive the minted tokens.
     * @param amount The amount of tokens to mint.
     * @param bankTxId A unique identifier for the bank transaction.
     */
    function mint(address to, uint256 amount, string calldata bankTxId) external onlyOwner {
        require(bytes(bankTxId).length > 0, "INRT: Bank transaction ID cannot be empty");
        require(!_processedBankTxIds[bankTxId], "INRT: Bank transaction ID already processed");

        _processedBankTxIds[bankTxId] = true;
        totalBankReserves += amount;
        _mint(to, amount);

        emit TokensMinted(to, amount, bankTxId);
    }

    /**
     * @notice Registers a withdrawal request from the authorized hook.
     * @dev This is called by the CryptoUPIHook during a swap.
     * @param requestId A unique identifier for the withdrawal request.
     * @param user The user requesting the withdrawal.
     * @param amount The amount of INRT to be withdrawn.
     * @param upiId The user's UPI ID for the bank transfer.
     */
    function requestWithdrawal(bytes32 requestId, address user, uint256 amount, string calldata upiId) external onlyAuthorizedHook {
        require(withdrawals[requestId].timestamp == 0, "INRT: Withdrawal request ID already exists");
        require(user != address(0), "INRT: Invalid user address");
        require(amount > 0, "INRT: Withdrawal amount must be positive");

        withdrawals[requestId] = Withdrawal({
            user: user,
            amount: amount,
            upiId: upiId,
            timestamp: block.timestamp,
            processed: false
        });

        emit WithdrawalRequested(requestId, user, amount, upiId);
    }

    /**
     * @notice Burns tokens for a withdrawal, initiated by the hook.
     * @dev The hook calls this after the owner initiates processing via the hook.
     * @param requestId The ID of the withdrawal request to burn tokens for.
     */
    function burnForWithdrawal(bytes32 requestId) external onlyAuthorizedHook {
        Withdrawal storage withdrawal = withdrawals[requestId];
        require(withdrawal.timestamp != 0, "INRT: Withdrawal request not found");
        // We do not check the 'processed' flag here, as marking it is a separate owner action.
        // The hook is responsible for ensuring this is not called multiple times for the same request.

        uint256 burnAmount = withdrawal.amount;
        address burnFrom = withdrawal.user;

        require(balanceOf(burnFrom) >= burnAmount, "INRT: Insufficient balance for withdrawal burn");

        totalBankReserves -= burnAmount;
        _burn(burnFrom, burnAmount);

        emit TokensBurned(burnFrom, burnAmount, requestId);
    }

    /**
     * @notice Marks a withdrawal as processed after off-chain payment is confirmed.
     * @param requestId The ID of the withdrawal request.
     */
    function markWithdrawalProcessed(bytes32 requestId) external onlyOwner {
        Withdrawal storage withdrawal = withdrawals[requestId];
        require(withdrawal.timestamp != 0, "INRT: Withdrawal request not found");
        require(!withdrawal.processed, "INRT: Withdrawal already processed");

        withdrawal.processed = true;
        emit WithdrawalProcessed(requestId);
    }

    /**
     * @notice Authorizes or de-authorizes a hook contract.
     * @param hook The address of the hook contract.
     * @param authorized True to authorize, false to de-authorize.
     */
    function setHook(address hook, bool authorized) external onlyOwner {
        authorizedHook = authorized ? hook : address(0);
        emit HookAuthorizationChanged(hook, authorized);
    }

    /**
     * @notice Pauses all token transfers.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpauses token transfers.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // --- View Functions ---

    /**
     * @notice Checks if a bank transaction ID has been used for minting.
     */
    function isBankTxIdProcessed(string calldata bankTxId) external view returns (bool) {
        return _processedBankTxIds[bankTxId];
    }

    /**
     * @notice Retrieves the details of a specific withdrawal request.
     */
    function getWithdrawalDetails(bytes32 requestId) external view returns (Withdrawal memory) {
        return withdrawals[requestId];
    }

    /**
     * @notice Calculates the backing ratio of reserves to total supply.
     * @return The ratio, scaled by 1e18 (e.g., 1e18 means a 1:1 ratio).
     */
    function getBackingRatio() external view returns (uint256) {
        uint256 currentTotalSupply = totalSupply();
        if (currentTotalSupply == 0) {
            return 0; // Avoid division by zero
        }
        return (totalBankReserves * (10**decimals())) / currentTotalSupply;
    }
}


/**
 * @title CryptoUPIHook
 * @notice A Uniswap v4 hook to facilitate UPI withdrawals when swapping USDT for INRT.
 * @dev This hook listens to swaps, emits a withdrawal request, and provides a method
 * for the contract owner to trigger the token burn after off-chain payment.
 */
contract CryptoUPIHook is BaseHook, Ownable {
    IINRT public inrtToken;
    address public usdtToken;
    PoolKey public poolKey;
    bool public isInitialized;

    mapping(bytes32 => bool) public processedRequests;

    event WithdrawalRequested(bytes32 indexed requestId, address indexed user, uint256 amount, string upiId);

    // Uniswap v4 hook callbacks are routed to functions based on the selector
    // returned by `getHookPermissions`. We request `afterSwap`.
    bytes16 private constant HOOK_PERMISSIONS = bytes16(IHooks.afterSwap.selector);

    // Empty constructor for pipeline requirements. The pool manager is set in `install`.
    constructor() {
    }

    /**
     * @notice Called by the PoolManager during pool creation to install the hook.
     * @dev This function initializes the hook with the pool's tokens and sets the
     *      pool manager address, which is msg.sender.
     * @param data ABI-encoded tuple of (address _usdtToken, address _inrtToken).
     */
    function install(bytes calldata data) external {
        require(!isInitialized, "Hook: Already initialized");
        // In Uniswap v4, `install` is called by the PoolManager.
        // We set i_poolManager to msg.sender on this first call.
        i_poolManager = IPoolManager(msg.sender);

        (address _usdtToken, address _inrtToken) = abi.decode(data, (address, address));

        inrtToken = IINRT(_inrtToken);
        usdtToken = _usdtToken;
        isInitialized = true;

        // Set currency0 and currency1 based on Uniswap's address sorting convention
        if (_usdtToken < _inrtToken) {
            poolKey.currency0 = _usdtToken;
            poolKey.currency1 = _inrtToken;
        } else {
            poolKey.currency0 = _inrtToken;
            poolKey.currency1 = _usdtToken;
        }
    }

    /**
     * @notice Specifies which hook callbacks this contract implements.
     */
    function getHookPermissions() external pure returns (bytes16) {
        return HOOK_PERMISSIONS;
    }

    /**
     * @notice Hook called after a swap. It initiates a lock to safely read the balance delta.
     * @param sender The address that initiated the swap.
     * @param params The parameters of the swap.
     * @param hookData The extra data passed by the user, containing withdrawal info.
     * @return The selector of this function, indicating it was handled.
     */
    function afterSwap(
        address sender,
        IPoolManager.SwapParams calldata params,
        bytes calldata hookData
    ) external poolManagerOnly returns (bytes4) {
        if (hookData.length > 0) {
            i_poolManager.lock(abi.encode(sender, hookData));
        }
        return CryptoUPIHook.afterSwap.selector;
    }

    /**
     * @notice Callback executed by the PoolManager after a lock is acquired.
     * @dev This is where we can safely read the results of the swap (balance deltas).
     * @param data The data passed from `afterSwap` via `lock`, along with balance deltas.
     */
    function lockAcquired(bytes calldata data) external poolManagerOnly returns (bytes memory) {
        (int256 amount0Delta, int256 amount1Delta, bytes memory originalData) =
            abi.decode(data, (int256, int256, bytes));

        (address sender, bytes memory hookData) = abi.decode(originalData, (address, bytes));
        (bytes32 requestId, string memory upiId) = abi.decode(hookData, (bytes32, string));

        require(address(inrtToken) != address(0), "Hook: INRT address not set");

        uint256 inrtReceived;

        // A USDT -> INRT swap means user receives a positive amount of INRT from the pool.
        // The delta is from the pool's perspective, so a token leaving the pool has a negative delta.
        if (poolKey.currency0 == address(inrtToken)) {
            if (amount0Delta < 0) inrtReceived = uint256(-amount0Delta);
        } else { // currency1 must be INRT
            if (amount1Delta < 0) inrtReceived = uint256(-amount1Delta);
        }

        if (inrtReceived > 0 && bytes(upiId).length > 0 && !processedRequests[requestId]) {
            emit WithdrawalRequested(requestId, sender, inrtReceived, upiId);
            inrtToken.requestWithdrawal(requestId, sender, inrtReceived, upiId);
        }

        return bytes("");
    }

    /**
     * @notice Called by the operator to process a withdrawal after off-chain payment.
     * @dev This function triggers the token burn in the INRT contract.
     * @param requestId The unique ID of the withdrawal to process.
     */
    function processWithdrawal(bytes32 requestId) external onlyOwner {
        require(!processedRequests[requestId], "Hook: Request already processed");
        processedRequests[requestId] = true;

        inrtToken.burnForWithdrawal(requestId);
    }

    // --- View Functions ---

    /**
     * @notice Helper function for clients to ABI-encode the hook data.
     * @param requestId A unique ID for the withdrawal request (e.g., a keccak256 hash).
     * @param upiId The user's UPI ID string.
     */
    function encodeHookData(bytes32 requestId, string calldata upiId) external pure returns (bytes memory) {
        return abi.encode(requestId, upiId);
    }

    /**
     * @notice Returns key details about the pool this hook is attached to.
     */
    function getPoolDetails() external view returns (bool, address, bytes32) {
        return (isInitialized, usdtToken, keccak256(abi.encode(poolKey.currency0, poolKey.currency1, poolKey.fee)));
    }
}

